#!/usr/bin/env python3
"""Copy authored environment deployment descriptors into a fresh export."""

from __future__ import annotations

import argparse
import shutil
from pathlib import Path


# ASHARIF 2026-11-26: every authored file in deployments/ survives an export (the export swaps the whole
# folder). default.json is generated by SQLcl and git-ignored, so it is not kept. Where the export wrote a file
# with the same name, the authored file wins (this has always been true for dev/staging/prod.json).
GENERATED_NAMES = frozenset({"default.json"})


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("existing_app", type=Path)
    parser.add_argument("staged_app", type=Path)
    args = parser.parse_args()

    existing = args.existing_app / "deployments"
    if existing.is_symlink():
        parser.error(f"deployments directory must not be a symbolic link: {existing}")
    if not existing.is_dir():
        return 0

    entries = sorted(existing.iterdir(), key=lambda path: path.name)
    for source in entries:
        if source.is_symlink():
            parser.error(f"deployment descriptor must not be a symbolic link: {source}")
        if source.is_dir():
            parser.error(f"deployments/ subfolders are not kept by an export; move {source} out first")

    staged = args.staged_app / "deployments"
    for source in entries:
        if source.name in GENERATED_NAMES or not source.is_file():
            continue
        staged.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, staged / source.name)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
